import csv
import sys
from collections import defaultdict


def read_rows(text):
    reader = csv.reader(text.splitlines())
    header = [h.strip() for h in next(reader)]
    return header, [row for row in reader if any(cell.strip() for cell in row)]


def to_number(text, kind):
    return kind(text.replace(",", ""))


def clean(header, rows):
    kept, problems = [], []
    for line_no, row in enumerate(rows, start=2):
        if len(row) != len(header):
            problems.append(f"line {line_no}: expected {len(header)} fields, got {len(row)}")
            continue
        rec = {name: cell.strip() for name, cell in zip(header, row)}
        if not rec["region"]:
            problems.append(f"line {line_no}: missing region")
            continue
        try:
            units = to_number(rec["units"], int)
        except ValueError:
            problems.append(f"line {line_no}: bad units {rec['units']!r}")
            continue
        if units <= 0:
            problems.append(f"line {line_no}: units must be positive")
            continue
        try:
            price = to_number(rec["price"], float)
        except ValueError:
            problems.append(f"line {line_no}: bad price {rec['price']!r}")
            continue
        rec.update(region=rec["region"].title(), units=units, price=price)
        kept.append(rec)
    return kept, problems


def revenue(rec):
    return rec["units"] * rec["price"]


def summarize(records):
    regions = sorted({r["region"] for r in records})
    by_region = {
        reg: {
            "units": sum(r["units"] for r in records if r["region"] == reg),
            "revenue": sum(revenue(r) for r in records if r["region"] == reg),
        }
        for reg in regions
    }
    by_product = defaultdict(int)
    for r in records:
        by_product[r["product"]] += r["units"]
    by_day = defaultdict(float)
    for r in records:
        by_day[r["date"]] += revenue(r)
    best_day = max(sorted(by_day), key=by_day.get) if by_day else None
    return {
        "by_region": dict(sorted(by_region.items(), key=lambda kv: (-kv[1]["revenue"], kv[0]))),
        "by_product": dict(sorted(by_product.items())),
        "best_day": best_day,
        "total": sum(revenue(r) for r in records),
    }


def main():
    header, rows = read_rows(sys.stdin.read())
    print(f"Loaded {len(rows)} rows, {len(header)} columns: {', '.join(header)}")
    kept, problems = clean(header, rows)
    print(f"Kept {len(kept)}, rejected {len(problems)}")
    for p in problems:
        print(f"  {p}")
    s = summarize(kept)
    print("Revenue by region:")
    for region, totals in s["by_region"].items():
        print(f"  {region}: {totals['revenue']:.2f}")
    print("Units by product:")
    for product, units in s["by_product"].items():
        print(f"  {product}: {units}")
    print(f"Best day: {s['best_day'] or '-'}")
    print(f"Total revenue: {s['total']:.2f}")


main()
